prompt --application/shared_components/plugins/template_component/theme_102_metric_card
begin
wwv_flow_imp_shared.create_plugin(
 p_id=>wwv_flow_imp.id(38792384613107703973)
,p_plugin_type=>'TEMPLATE COMPONENT'
,p_theme_id=>nvl(wwv_flow_application_install.get_theme_id, '102')
,p_name=>'THEME_102$METRIC_CARD'
,p_display_name=>'Metric Card'
,p_apexlang_name=>'metricCard'
,p_supported_component_types=>'PARTIAL:REPORT'
,p_image_prefix=>nvl(wwv_flow_application_install.get_static_plugin_file_prefix('TEMPLATE COMPONENT','THEME_102$METRIC_CARD'),'')
,p_partial_template=>wwv_flow_string.join(wwv_flow_t_varchar2(
'{if APEX$IS_LAZY_LOADING/}',
'  <div class="t-MetricCard" aria-hidden="true">',
'    <div class="t-MetricCard-body">',
'      {if ?TITLE%assigned/}<div class="t-MetricCard-title #TITLE_CSS_CLASSES# is-placeholder"></div>{endif/}',
'      {if ?METRIC%assigned/}<div class="t-MetricCard-metric #METRIC_CSS_CLASSES# is-placeholder"></div>{endif/}',
'      {if ?META%assigned/}<div class="t-MetricCard-meta #META_CSS_CLASSES# is-placeholder"></div>{endif/}',
'    </div>',
'    {if DISPLAY_BADGE/}',
'    <div class="t-MetricCard-badge">',
'      {with/}',
'        LABEL:=',
'        VALUE:=',
'        SIZE:=#BADGE_SIZE#',
'        SHAPE:=#BADGE_SHAPE#',
'      {apply THEME$BADGE/}',
'    </div>',
'    {endif/}',
'  </div>',
'{else/}',
'  {if LINK/}<a href="#LINK#" #LINK_ATTR#{else/}<div{endif/} class="t-MetricCard u-color-var">',
'    {if ?APEX$SELECTOR%assigned/}<div class="t-MetricCard-selection">#APEX$SELECTOR#</div>{endif/}',
'    <div class="t-MetricCard-body #AVATAR_POSITION# #AVATAR_ALIGNMENT#">',
'      {if DISPLAY_AVATAR/}',
'      <div class="t-MetricCard-avatar{if ?AVATAR_STYLE/} #AVATAR_STYLE#{endif/}">',
'        {with/}',
'          TYPE:=#AVATAR_TYPE#',
'          IMAGE:=#AVATAR_IMAGE#',
'          ICON:=#AVATAR_ICON#',
'          INITIALS:=#AVATAR_INITIALS#',
'          SIZE:=#AVATAR_SIZE#',
'          SHAPE:=#AVATAR_SHAPE#',
'        {apply THEME$AVATAR/}',
'      </div>',
'      {endif/}',
'      <div class="t-MetricCard-content">',
'        {if ?TITLE/}<div class="t-MetricCard-title #TITLE_CSS_CLASSES#">#TITLE#</div>{endif/}',
'        {if ?METRIC/}<div class="t-MetricCard-metric #METRIC_CSS_CLASSES#">#METRIC#</div>{endif/}',
'        {if ?META/}<div class="t-MetricCard-meta #META_CSS_CLASSES#">#META#</div>{endif/}',
'      </div>',
'    </div>',
'    {if DISPLAY_BADGE/}',
'    <div class="t-MetricCard-badge">',
'      {with/}',
'        LABEL_DISPLAY:=#BADGE_LABEL_DISPLAY#',
'        LABEL:=#BADGE_LABEL#',
'        SIZE:=#BADGE_SIZE#',
'        VALUE:=#BADGE_VALUE#',
'        ICON:=#BADGE_ICON#',
'        SHAPE:=#BADGE_SHAPE#',
'        STYLE:=#BADGE_STYLE#',
'        STATE:=#BADGE_STATE#',
'      {apply THEME$BADGE/}',
'    </div>',
'  {endif/}',
'  {if LINK/}</a>{else/}</div>{endif/}',
'{endif/}',
''))
,p_default_escape_mode=>'HTML'
,p_translate_this_template=>false
,p_api_version=>1
,p_report_body_template=>wwv_flow_string.join(wwv_flow_t_varchar2(
