'/* ===== Orders IR ===== */',
'.gm-orders-ir .t-Report-colHead {',
'    background: #f8f9fa;',
'    color: #7f8c8d;',
'    font-size: 0.75rem;',
'    font-weight: 700;',
'    text-transform: uppercase;',
'    letter-spacing: 0.8px;',
'    padding: 12px 14px;',
'}',
'',
'.gm-orders-ir .t-Report-cell {',
'    padding: 12px 14px;',
'    font-size: 0.85rem;',
'    color: #2c3e50;',
'    vertical-align: middle;',
'}',
'',
'.gm-orders-ir .t-Report-row:hover {',
'    background: #f8fbff;',
'}',
'',
'/* ===== Order Status Badges ===== */',
'.gm-ord-status {',
'    display: inline-block;',
'    padding: 3px 10px;',
'    border-radius: 12px;',
'    font-size: 0.7rem;',
'    font-weight: 600;',
'    text-transform: uppercase;',
'    letter-spacing: 0.5px;',
'    white-space: nowrap;',
'}',
'.gm-ord-pending    { background: #fff3cd; color: #856404; }',
'.gm-ord-processing { background: #cce5ff; color: #004085; }',
'.gm-ord-cancelled  { background: #f8d7da; color: #721c24; }',
'.gm-ord-rejected   { background: #f5c6cb; color: #721c24; }',
'.gm-ord-shipped    { background: #d1ecf1; color: #0c5460; }',
'.gm-ord-delivered  { background: #d4edda; color: #155724; }',
'.gm-ord-refunded   { background: #e2e3e5; color: #383d41; }',
'.gm-ord-returned   { background: #ffeaa7; color: #856404; }',
'.gm-ord-completed  { background: #d4edda; color: #155724; }',
'.gm-ord-closed     { background: #e2e3e5; color: #383d41; }',
'',
'/* ===== Edit Icon ===== */',
'.gm-edit-link {',
'    display: inline-flex;',
'    align-items: center;',
'    justify-content: center;',
'    width: 32px;',
'    height: 32px;',
'    border-radius: 8px;',
'    background: #eaf4fd;',
'    color: #3498db !important;',
'    text-decoration: none !important;',
'    transition: all 0.2s ease;',
'}',
'.gm-edit-link:hover {',
'    background: #3498db;',
'    color: #ffffff !important;',
'    transform: scale(1.1);',
'}'))
