wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(42482882010862984209)
,p_plug_name=>'Orders'
,p_static_id=>'orders'
,p_title=>'Orders'
,p_region_css_classes=>'gm-orders-ir'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>wwv_flow_imp.id(38792036588729703226)
,p_plug_display_sequence=>20
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT o.order_id,',
'       o.order_date,',
'       c.cust_first_name || '' '' || c.cust_last_name AS customer_name,',
'       o.order_mode,',
'       CASE o.order_status',
'           WHEN 0 THEN ''<span class="gm-ord-status gm-ord-pending">Pending</span>''',
'           WHEN 1 THEN ''<span class="gm-ord-status gm-ord-processing">Processing</span>''',
'           WHEN 2 THEN ''<span class="gm-ord-status gm-ord-cancelled">Cancelled</span>''',
'           WHEN 3 THEN ''<span class="gm-ord-status gm-ord-rejected">Rejected</span>''',
'           WHEN 4 THEN ''<span class="gm-ord-status gm-ord-shipped">Shipped</span>''',
'           WHEN 5 THEN ''<span class="gm-ord-status gm-ord-delivered">Delivered</span>''',
'           WHEN 6 THEN ''<span class="gm-ord-status gm-ord-refunded">Refunded</span>''',
'           WHEN 7 THEN ''<span class="gm-ord-status gm-ord-returned">Returned</span>''',
'           WHEN 8 THEN ''<span class="gm-ord-status gm-ord-completed">Completed</span>''',
'           WHEN 9 THEN ''<span class="gm-ord-status gm-ord-closed">Closed</span>''',
'           ELSE ''Unknown''',
'       END AS order_status_html,',
'       o.order_total,',
'       e.first_name || '' '' || e.last_name AS sales_rep,',
'       ''<a href="'' || ',
'       APEX_PAGE.GET_URL(',
'           p_page   => 7,',
'           p_items  => ''P7_ORDER_ID'',',
'           p_values => o.order_id',
'       ) || ',
'       ''" class="gm-edit-link" title="Edit Order"><span class="fa fa-pencil"></span></a>'' AS edit_link',
'FROM   oehr_orders o',
'LEFT JOIN oehr_customers c ON o.customer_id = c.customer_id',
'LEFT JOIN oehr_employees e ON o.sales_rep_id = e.employee_id',
'ORDER BY o.order_date DESC'))
,p_plug_source_type=>'NATIVE_IR'
