wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(41429489774137662914)
,p_plug_name=>'Customer Info'
,p_static_id=>'customer-info'
,p_title=>'Customer Info'
,p_region_template_options=>'#DEFAULT#:t-Region--hideHeader js-addHiddenHeadingRoleDesc:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(38792057947742703242)
,p_plug_display_sequence=>30
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_first_name    oehr_customers.cust_first_name%TYPE;',
'    v_last_name     oehr_customers.cust_last_name%TYPE;',
'    v_email         oehr_customers.cust_email%TYPE;',
'    v_phone         oehr_customers.phone_number%TYPE;',
'    v_city          oehr_customers.city%TYPE;',
'    v_credit_limit  oehr_customers.credit_limit%TYPE;',
'    v_account_mgr   VARCHAR2(200);',
'BEGIN',
'    SELECT c.cust_first_name,',
'           c.cust_last_name,',
'           c.cust_email,',
'           c.phone_number,',
'           c.city,',
'           c.credit_limit,',
'           e.first_name || '' '' || e.last_name',
'    INTO   v_first_name,',
'           v_last_name,',
'           v_email,',
'           v_phone,',
'           v_city,',
'           v_credit_limit,',
'           v_account_mgr',
'    FROM   oehr_customers c',
'    LEFT JOIN oehr_employees e ON c.account_mgr_id = e.employee_id',
'    WHERE  c.customer_id = :P11_CUSTOMER_ID;',
'',
'    IF v_first_name IS NULL THEN',
'        RETURN ''<div class="gm-360-empty">Customer not found.</div>'';',
'    END IF;',
'',
'    RETURN',
'        ''<div class="gm-360-info-card">'' ||',
'            ''<div class="gm-360-info-header">'' ||',
'                ''<div class="gm-360-avatar"><span class="fa fa-user" aria-hidden="true"></span></div>'' ||',
'                ''<div class="gm-360-info-name">'' ||',
'                    ''<div class="gm-360-name-full">'' || apex_escape.html(v_first_name || '' '' || v_last_name) || ''</div>'' ||',
'                    ''<div class="gm-360-name-email">'' || apex_escape.html(v_email) || ''</div>'' ||',
'                ''</div>'' ||',
'            ''</div>'' ||',
'            ''<div class="gm-360-info-grid">'' ||',
'                ''<div class="gm-360-field">'' ||',
'                    ''<div class="gm-360-field-label"><span class="fa fa-map-marker"></span> City</div>'' ||',
'                    ''<div class="gm-360-field-value">'' || apex_escape.html(v_city) || ''</div>'' ||',
'                ''</div>'' ||',
'                ''<div class="gm-360-field">'' ||',
'                    ''<div class="gm-360-field-label"><span class="fa fa-phone"></span> Phone</div>'' ||',
'                    ''<div class="gm-360-field-value">'' || apex_escape.html(v_phone) || ''</div>'' ||',
'                ''</div>'' ||',
'                ''<div class="gm-360-field">'' ||',
'                    ''<div class="gm-360-field-label"><span class="fa fa-credit-card"></span> Credit Limit</div>'' ||',
'                    ''<div class="gm-360-field-value">'' || apex_escape.html(TO_CHAR(v_credit_limit, ''FM999G999G990D00'')) || ''</div>'' ||',
'                ''</div>'' ||',
'                ''<div class="gm-360-field">'' ||',
'                    ''<div class="gm-360-field-label"><span class="fa fa-briefcase"></span> Account Manager</div>'' ||',
'                    ''<div class="gm-360-field-value">'' || apex_escape.html(v_account_mgr) || ''</div>'' ||',
'                ''</div>'' ||',
'            ''</div>'' ||',
'        ''</div>'';',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
'        RETURN ''<div class="gm-360-empty">Customer not found.</div>'';',
'END;'))
,p_lazy_loading=>false
