,p_plug_template=>wwv_flow_imp.id(38792057947742703242)
,p_plug_display_sequence=>40
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_total_orders  NUMBER;',
'    v_total_spent   NUMBER;',
'    v_avg_order     NUMBER;',
'    v_last_order    DATE;',
'BEGIN',
unistr('    -- Query \0648\0627\062D\062F \064A\062C\064A\0628 \0627\0644\0640 4 \0642\064A\0645'),
'    SELECT COUNT(*),',
'           NVL(SUM(order_total), 0),',
'           NVL(AVG(order_total), 0),',
'           MAX(order_date)',
'    INTO   v_total_orders,',
'           v_total_spent,',
'           v_avg_order,',
'           v_last_order',
'    FROM   oehr_orders',
'    WHERE  customer_id = :P11_CUSTOMER_ID;',
'',
unistr('    -- \0628\0646\0627\0621 \0627\0644\0640 HTML'),
'    RETURN',
'        ''<div class="gm-kpi-grid">'' ||',
'',
'            -- Card 1: Total Orders',
'            ''<div class="gm-kpi-card gm-kpi-blue">'' ||',
'                ''<div class="gm-kpi-icon"><span class="fa fa-shopping-cart"></span></div>'' ||',
'                ''<div class="gm-kpi-label">Total Orders</div>'' ||',
'                ''<div class="gm-kpi-value">'' || v_total_orders || ''</div>'' ||',
'            ''</div>'' ||',
'',
'            -- Card 2: Total Spent',
'            ''<div class="gm-kpi-card gm-kpi-green">'' ||',
'                ''<div class="gm-kpi-icon"><span class="fa fa-dollar"></span></div>'' ||',
'                ''<div class="gm-kpi-label">Total Spent</div>'' ||',
'                ''<div class="gm-kpi-value">$'' || TO_CHAR(v_total_spent, ''FM999G999G990D00'') || ''</div>'' ||',
'            ''</div>'' ||',
'',
'            -- Card 3: Avg Order',
'            ''<div class="gm-kpi-card gm-kpi-orange">'' ||',
'                ''<div class="gm-kpi-icon"><span class="fa fa-bar-chart"></span></div>'' ||',
'                ''<div class="gm-kpi-label">Avg Order</div>'' ||',
'                ''<div class="gm-kpi-value">$'' || TO_CHAR(v_avg_order, ''FM999G999G990D00'') || ''</div>'' ||',
'            ''</div>'' ||',
'',
'            -- Card 4: Last Order',
'            ''<div class="gm-kpi-card gm-kpi-purple">'' ||',
'                ''<div class="gm-kpi-icon"><span class="fa fa-calendar"></span></div>'' ||',
'                ''<div class="gm-kpi-label">Last Order</div>'' ||',
'                ''<div class="gm-kpi-value">'' ||',
'                    CASE WHEN v_last_order IS NULL',
'                         THEN ''No Orders''',
'                         ELSE TO_CHAR(v_last_order, ''DD-MON-YY'')',
'                    END ||',
'                ''</div>'' ||',
'            ''</div>'' ||',
'',
'        ''</div>'';',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        RETURN ''<div class="gm-360-empty">Error loading KPIs: '' ||',
'               apex_escape.html(SQLERRM) || ''</div>'';',
'END;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
,p_created_on=>wwv_flow_imp.dz('20260928061316Z')
,p_updated_on=>wwv_flow_imp.dz('20260928061542Z')
,p_created_by=>'OMRFOX690@GMAIL.COM'
,p_updated_by=>'OMRFOX690@GMAIL.COM'
);
