prompt --application/pages/page_00022
begin
wwv_flow_imp_page.create_page(
 p_id=>22
,p_name=>'Customer Details'
,p_alias=>'CUSTOMER-DETAILS'
,p_step_title=>'Customer Details'
,p_autocomplete_on_off=>'OFF'
,p_group_id=>wwv_flow_imp.id(39744994118217125610)
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* ===== Customer Actions ===== */',
'.gm-cust-actions {',
'    display: grid;',
'    grid-template-columns: repeat(2, 1fr);',
'    gap: 16px;',
'    margin-top: 8px;',
'}',
'',
'.gm-cust-btn {',
'    display: flex;',
'    align-items: center;',
'    gap: 14px;',
'    padding: 18px 20px;',
'    background: #ffffff;',
'    border: 1px solid #e9ecef;',
'    border-radius: 12px;',
'    text-decoration: none !important;',
'    color: inherit !important;',
'    transition: all 0.25s ease;',
'    position: relative;',
'    overflow: hidden;',
'}',
'',
'.gm-cust-btn::before {',
'    content: "";',
'    position: absolute;',
'    top: 0; left: 0; bottom: 0;',
'    width: 4px;',
'    background: #3498db;',
'    transition: width 0.25s ease;',
'}',
'',
'.gm-cust-btn:hover {',
'    transform: translateY(-3px);',
'    box-shadow: 0 8px 20px rgba(52, 152, 219, 0.15);',
'    border-color: #3498db;',
'}',
'',
'.gm-cust-btn:hover::before {',
'    width: 6px;',
'}',
'',
'.gm-cust-btn-icon {',
'    flex-shrink: 0;',
'    width: 48px;',
'    height: 48px;',
'    border-radius: 12px;',
'    background: #eaf4fd;',
