 p_id=>wwv_flow_imp.id(40671312255790328307)
,p_process_sequence=>10
,p_process_point=>'AFTER_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Load Data'
,p_static_id=>'load-data'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'for l_feedback in (',
'   select page_id,',
'          page_name,',
'          case feedback_rating',
'                when 1 then ''<span class="fa fa-frown-o feedback-negative" aria-hidden="true" title="Negative"></span>'' ',
'                when 2 then ''<span class="fa fa-emoji-neutral feedback-neutral" aria-hidden="true" title="Neutral"></span>''  ',
'                when 3 then ''<span class="fa fa-smile-o feedback-positive" aria-hidden="true" title="Positive"></span>'' ',
'                end rating_icon,',
'          lower(created_by) || '' - '' || apex_util.get_since(created_on) filed,',
'          feedback,',
'          public_response,',
'          feedback_status,',
'          http_user_agent',
'     from apex_team_feedback',
'    where feedback_id = :P10018_ID )',
'loop',
'   :P10018_PAGE_ID         := l_feedback.page_id||''. ''||l_feedback.page_name;',
'   :P10018_FILED           := l_feedback.filed;',
'   :P10018_RATING_ICON     := l_feedback.rating_icon;',
'   :P10018_FEEDBACK        := l_feedback.feedback;',
'   :P10018_RESPONSE        := l_feedback.public_response;',
'   :P10018_FEEDBACK_STATUS := l_feedback.feedback_status;',
'   :P10018_USER_AGENT      := l_feedback.http_user_agent;',
'end loop;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>40671312255790328307
,p_created_on=>wwv_flow_imp.dz('20260923055921Z')
,p_updated_on=>wwv_flow_imp.dz('20260923055921Z')
,p_created_by=>'OMRFOX690@GMAIL.COM'
,p_updated_by=>'OMRFOX690@GMAIL.COM'
);
